  app.querySelector("#access-share-form")?.addEventListener("submit",async e=>{e.preventDefault();if(!await requireMfa(supabase,app))return;const f=Object.fromEntries(new FormData(e.target));f.included_elements=String(f.included_elements||"").split(",").map(x=>x.trim()).filter(Boolean);f.grantee_identifier_type=String(f.grantee_identifier).includes("@")?"email":"phone";const {data,error}=await supabase.functions.invoke("create-record-share",{body:f});e.target.querySelector(".form-result").innerHTML=error||data?.error?h(error?.message||data.error):`Link: <code>${h(data.share_url)}</code><br>Temporary password: <code>${h(data.temporary_password)}</code>`;if(!error&&!data?.error&&navigator.share)await navigator.share({title:"Healthcarology record access",text:`${data.share_url}\nTemporary password: ${data.temporary_password}`}).catch(()=>{})});
