export async function renderHealthDepartment(supabase,app,shell){
  const {data:memberships}=await supabase.from("health_department_memberships").select("jurisdiction_id,health_jurisdictions(name,jurisdiction_type,authority_level)").eq("active",true);const data=await commonData(supabase,null),ids=(memberships||[]).map(x=>x.jurisdiction_id);const {data:rules}=ids.length?await supabase.from("health_department_rules").select("id,jurisdiction_id,rule_category,name,description,requirements,effective_from,effective_to,active").in("jurisdiction_id",ids).order("effective_from",{ascending:false}):{data:[]};
  app.innerHTML=shell("Health Department portal","Jurisdiction-scoped public health oversight",`<nav class="portal-links"><a href="/health-department">Health department</a><a href="#rules">Maternal-health rules</a><a href="#analytics">Analytics and heat map</a><a href="#support">Support</a></nav><section class="card"><h2>Authorized jurisdictions</h2>${(memberships||[]).map(x=>`<div class="row"><b>${h(x.health_jurisdictions?.name)}</b><span>${h(x.health_jurisdictions?.authority_level||x.health_jurisdictions?.jurisdiction_type)}</span></div>`).join("")||"No jurisdiction has been assigned to this account."}</section><section class="card" id="rules"><h2>Prenatal and partograph rules</h2><p>Rules apply only within the authority assigned by Healthcarology.</p><form id="health-rule-form"><label>Jurisdiction<select name="jurisdiction_id" required>${(memberships||[]).map(x=>`<option value="${h(x.jurisdiction_id)}">${h(x.health_jurisdictions?.name)} · ${h(x.health_jurisdictions?.authority_level)}</option>`).join("")}</select></label><label>Rule category<select name="rule_category"><option value="prenatal_visit">Prenatal visit</option><option value="partograph">Partograph</option><option value="maternal_alert">Maternal alert</option><option value="reporting">Reporting</option></select></label><label>Rule name<input name="name" required></label><label>Description<textarea name="description" required></textarea></label><label>Requirements (structured JSON)<textarea name="requirements" placeholder='{"required_fields":["systolic_bp","fetal_heart_rate"]}' required></textarea></label><label>Effective from<input type="date" name="effective_from" required></label><label>Effective to<input type="date" name="effective_to"></label><button class="button">Publish rule</button><p class="form-result"></p></form>${(rules||[]).map(x=>`<div class="row"><span><b>${h(x.name)}</b><small>${h(x.rule_category)} · ${h(x.effective_from)}${x.effective_to?` to ${h(x.effective_to)}`:""}</small></span><span class="status">${x.active?"active":"inactive"}</span></div>`).join("")||"No rules published."}</section><section id="analytics">${heatmapCard(data.heat)}</section><section class="feature-grid" id="support">${messageCard(data.threads)+communityCard(data.communities)+supportCard(data.groups,data.tickets)}</section>`);await wireCommon(supabase,app,null);
  app.querySelector("#health-rule-form")?.addEventListener("submit",async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target));try{body.requirements=JSON.parse(body.requirements)}catch{e.target.querySelector(".form-result").textContent="Requirements must be valid JSON.";return}if(!body.effective_to)body.effective_to=null;body.created_by=(await supabase.auth.getUser()).data.user.id;const r=await supabase.from("health_department_rules").insert(body);e.target.querySelector(".form-result").textContent=r.error?.message||"Jurisdiction rule published.";if(!r.error)setTimeout(()=>location.reload(),500)});
  organizePortalSections(app);
}
